var payload = msg.payload;
if (!payload || !payload.top_signals || payload.top_signals.length === 0) {
    msg.harmonic = { status: 'no_signals', ts: new Date().toISOString() };
    return [msg, null];
}
var top = payload.top_signals[0];
var ff  = top.flowform || {};
msg.harmonic = {
    ts:              new Date().toISOString(),
    total_signals:   payload.total_signals,
    top_domain:      top.domain,
    top_asset:       top.asset,
    top_signal_type: top.signal_type,
    edge_pct:        top.edge_pct,
    harmonic_score:  ff.hybrid_harmonic_score,
    curvature:       ff.curvature_score,
    resonance:       ff.resonance_score,
    persistence:     ff.persistence_score,
    phi_bonus:       ff.phi_resonance_bonus,
    all_top:         payload.top_signals.slice(0, 5)
};
msg.topic = 'luma_harmonic_edge';
return [msg, msg];

var h = msg.harmonic;
msg.payload = {
    type:    'harmonic_update',
    data:    h,
    source:  'node_red'
};
return msg;

// Converts flat node list into Unity XR field data
// Each node maps to a 3D position using harmonic score + phi geometry
var data = msg.payload;
var nodes = (data && data.nodes) ? data.nodes : [];
var phi = (data && data.phi) ? data.phi : 1.618;

var mapped = nodes.map(function(n, i) {
    // Fibonacci spiral positioning
    var angle = i * phi * Math.PI * 2;
    var radius = 2 + (n.harmonic_score / 100) * 8;
    return {
        id:            n.id,
        asset:         n.asset,
        domain:        n.domain,
        signal_type:   n.signal_type,
        harmonic_score:n.harmonic_score,
        edge_pct:      n.edge_pct,
        curvature:     n.curvature,
        resonance:     n.resonance,
        // 3D position for Unity scene
        pos_x: Math.round(radius * Math.cos(angle) * 100) / 100,
        pos_y: Math.round((n.harmonic_score / 100) * 5 * 100) / 100,
        pos_z: Math.round(radius * Math.sin(angle) * 100) / 100,
        // Color encoding: domain
        color: n.domain === 'crypto'  ? '#66f8d7'
             : n.domain === 'sports'  ? '#ffdc7c'
             : n.domain === 'infra'   ? '#a78bfa'
             : '#ffffff',
        // Scale by edge quality
        scale: Math.max(0.3, n.harmonic_score / 50)
    };
});

msg.unity_field = {
    schema:        'luma_harmonic_field_v1',
    generated_utc: data ? data.generated_utc : new Date().toISOString(),
    phi:           phi,
    node_count:    mapped.length,
    nodes:         mapped
};
msg.payload = msg.unity_field;
msg.topic   = 'unity_harmonic_field';
return msg;

var t = msg.payload || {};
var ex = t.execution || {};
var alpha = t.alpha || {};
msg.payload = {
  type: 'trading_update',
  source: 'node_red',
  data: {
    ts: new Date().toISOString(),
    mode: t.mode || 'paper',
    status: t.status || 'unknown',
    bankroll: ex.current_bankroll || 0,
    open_positions: ex.open_positions || 0,
    total_trades: ex.total_trades || 0,
    win_rate_pct: ex.win_rate_pct || 0,
    profit_factor: ex.profit_factor || 0,
    moonshots: alpha.moonshots || 0,
    signals_generated: alpha.signals_generated || 0
  }
};
msg.topic = 'luma_trading_summary';
return msg;

var d = msg.payload || {};
var s = d.summary || {};
var spikes = d.real_spike_alerts || [];
var top = d.top_signals || [];
// Only forward if fleet is live
if (d.status !== 'running') { return null; }
msg.payload = {
  type: 'mesh_update',
  source: 'node_red',
  data: {
    ts: new Date().toISOString(),
    status: d.status,
    freshness_sec: d.freshness_sec || 0,
    total_watched: s.total_watched || 0,
    symbols_with_data: s.symbols_with_data || 0,
    active_spikes: s.active_spikes || 0,
    real_spikes: s.real_spikes || 0,
    top_signal: top.length > 0 ? { symbol: top[0].symbol, price: top[0].last_price, z: top[0].spike_z_score } : null,
    spike_alerts: spikes.slice(0, 5).map(function(sp) {
      return { symbol: sp.symbol, direction: sp.spike_direction, z: sp.spike_z_score, score: sp.spike_score, price: sp.last_price };
    })
  }
};
msg.topic = 'luma_symbol_mesh';
return msg;
